namespace WsdlGenerator.Emit;

/// <summary>A file the generator produces, written only when its content actually changed.</summary>
internal sealed record GeneratedFile(string Path, string Content)
{
    public const string Header =
        """
        //------------------------------------------------------------------------------
        // <auto-generated>
        //     Generated by WsdlGenerator from the schemas mirrored in wsdl/.
        //
        //     Edits to this file are lost on the next run. To change the output, change
        //     the generator; to pick up specification changes, run wsdl/fetch.sh first.
        //     See doc/codegen.md.
        // </auto-generated>
        //------------------------------------------------------------------------------
        """;

    /// <summary>
    /// Header for the runtime, which is emitted from source embedded in the generator rather than
    /// compiled from a schema, and so is changed in a different place.
    /// </summary>
    public const string RuntimeHeader =
        """
        //------------------------------------------------------------------------------
        // <auto-generated>
        //     Generated by WsdlGenerator: the runtime the generated clients and services drive.
        //
        //     Edits to this file are lost on the next run. To change it, change the source it is
        //     emitted from, in the generator's Runtime/ directory. See doc/codegen.md.
        // </auto-generated>
        //------------------------------------------------------------------------------
        """;

    /// <summary>
    /// Writes the file if its content differs. Leaving unchanged files alone keeps their
    /// timestamps stable, so an incremental build does not rebuild every project after a run
    /// that changed nothing.
    /// </summary>
    public bool WriteIfChanged()
    {
        if (File.Exists(Path) && File.ReadAllText(Path) == Content) return false;

        Directory.CreateDirectory(System.IO.Path.GetDirectoryName(Path)!);
        File.WriteAllText(Path, Content);
        return true;
    }
}
